const guide=l=>add({kind:'guided',minutes:30,starter:l.example,solution:l.example,...l});
guide({id:'eng-01',track:'engineering',title:'从网页走到自己的电脑',intro:'网页练习帮你跨过第一道门槛。接下来需要在自己的电脑上创建文件、打开终端并运行程序。',concept:'编辑器用来修改文件，终端用来发送命令，解释器负责执行代码。当前目录决定相对路径从哪里开始查找。',example:'mkdir codepath-lab\ncd codepath-lab\npy --version\npy hello.py',explain:'Windows 可从 python.org 安装 Python，从 code.visualstudio.com 安装 VS Code。打开 VS Code 的“文件 → 打开文件夹”，选 codepath-lab；新建 hello.py，写入 print("你好")，然后打开“终端 → 新建终端”。如果 py 不存在，确认安装完成后重开终端，也可试 python --version。',steps:['创建独立练习文件夹，使用 VS Code 打开它。','新建 hello.py，保存一行 print("你好")。','在该文件夹的终端运行 py hello.py。修改文字、保存并再次运行。'],checks:['终端显示 Python 版本','hello.py 在正确文件夹内','修改文字后重新运行，输出随之变化'],quiz:{q:'修改代码后输出没变，先检查什么？',options:['是否保存了文件，以及运行的是否是同一个文件','立即重新安装整个系统','多点几次键盘'],answer:0,explanation:'先核对文件路径、保存状态和终端当前目录，这是定位环境问题的基础。'},hint:'在 VS Code 文件树里确认 hello.py；终端提示符路径应是 codepath-lab。',reflection:'文件夹、文件、程序进程分别是什么？用自己的话各解释一句。',source:'https://docs.python.org/3/using/windows.html'});
guide({id:'eng-02',track:'engineering',title:'虚拟环境与依赖：每个项目有自己的工具箱',intro:'不同项目可能需要不同版本的库。虚拟环境把依赖隔开，让项目更容易复现。',concept:'第三方包是其他人编写的可复用代码。pip 安装包；venv 创建隔离环境。requirements.txt 记录需要的包及版本。',example:'py -m venv .venv\n./.venv/Scripts/python.exe -m pip --version\n./.venv/Scripts/python.exe -m pip freeze > requirements.txt',explain:'这里直接使用虚拟环境里的 Python，不要求修改 PowerShell 执行策略，也不依赖激活脚本。后续命令中的 python 都应指向这个解释器。',steps:['在练习文件夹创建 .venv。','用 .venv 内的 Python 查看 pip 版本，观察输出路径。','生成 requirements.txt。此时没有额外包，文件可能为空，这是正常结果。'],checks:['.venv 文件夹已创建','pip 路径指向 .venv','能解释 requirements.txt 的作用'],quiz:{q:'虚拟环境主要解决什么问题？',options:['让代码自动变正确','隔离不同项目的依赖','自动提交 GitHub'],answer:1,explanation:'它隔离依赖，但不能修复程序逻辑，也不等于操作系统级安全隔离。'},hint:'所有命令都在项目目录运行。不要把 .venv 目录提交进版本控制。',reflection:'别人只有你的 .py 文件，没有依赖说明，能顺利复现吗？',source:'https://docs.python.org/3/library/venv.html'});
guide({id:'eng-03',track:'engineering',title:'Git：让修改有记录、可比较',intro:'当 AI 或你修改了多个文件，Git 能展示到底改了什么，并为每个稳定阶段留下记录。',concept:'工作区是正在编辑的文件；暂存区是本次准备提交的改动；提交是一个有说明的快照。git diff 展示尚未暂存的修改。',example:'git init\ngit status\ngit add hello.py .gitignore\ngit commit -m "Add hello program"\ngit diff',explain:'先从 git-scm.com 安装 Git。新建 .gitignore，写入 .venv/、__pycache__/ 和 .env，每项一行。提交需要配置 Git 用户名和邮箱，按自己的信息设置；本课只在本机操作，不需要发布到 GitHub。',steps:['在练习目录初始化仓库，创建 .gitignore。','仅暂存 hello.py 和 .gitignore；git status 确认后提交。','修改 hello.py 的问候语，运行 git diff，指出修改前后内容。'],checks:['初始提交存在','能用 git status 查看状态','能解释 git diff 中的加号和减号','环境文件和密钥未被暂存'],quiz:{q:'AI 修改后，接受代码前应该做什么？',options:['只看 AI 的总结','先看 diff，理解修改，再运行相关测试','只看文件数量'],answer:1,explanation:'修改说明不是证据。实际差异和测试结果才能帮助判断影响。'},hint:'git diff --staged 查看已暂存内容；git diff 查看未暂存内容。',reflection:'为什么每次提交应围绕一个清晰的小目标？'});
guide({id:'eng-04',track:'engineering',title:'HTTP 与 JSON：前后端怎样说话',intro:'浏览器向服务器发送请求，服务器返回响应。后端开发的大量工作，就是定义这套对话规则。',concept:'URL 指明资源，方法表达动作，状态码表达结果。GET 通常读取，POST 通常创建。200 表示成功，404 表示未找到，500 表示服务器错误。',example:'GET /tasks/1 HTTP/1.1\n\nHTTP/1.1 200 OK\nContent-Type: application/json\n\n{"id":1,"title":"学习"}',explain:'上面是协议示意，不是直接执行的 Python。JSON 是响应体，状态码和响应头不属于 JSON 本身。',steps:['在浏览器开发者工具打开 Network（网络）面板，再刷新一个普通网页。','选择一个请求，找到 URL、方法、状态码、响应体。','用笔记分别记录这四项，不复制账号令牌或 Cookie。'],checks:['找到一次真实请求','能区分请求与响应','能识别状态码与响应体'],quiz:{q:'接口返回 200，是否证明业务结果一定正确？',options:['是，200 就代表没有 bug','不一定，还要检查响应内容与业务约定','只要是 JSON 就正确'],answer:1,explanation:'协议层成功不等于业务正确。返回空列表、错误计算也可能带着 200。'},hint:'Network 面板的 Headers 看方法和状态，Response 看响应体。',reflection:'网络失败、HTTP 错误、业务错误应该如何区分？',source:'https://developer.mozilla.org/zh-CN/docs/Web/HTTP/Overview'});
guide({id:'eng-05',track:'engineering',title:'测试与调试：定位问题的证据链',intro:'当输出不对，猜测并重复改代码通常很慢。先复现，再缩小范围，最后用测试保护修复。',concept:'单元测试检查一个小单元；集成测试检查组件如何协作；断点让你暂停程序、观察变量。日志应记录关键状态，避免包含密码和令牌。',example:'# calc.py\ndef total(items):\n    return sum(items)\n\n# test_calc.py\nfrom calc import total\ndef test_total():\n    assert total([2, 3]) == 5\ndef test_empty():\n    assert total([]) == 0',explain:'在虚拟环境安装 pytest：.\\.venv\\Scripts\\python.exe -m pip install pytest。将示例按注释分成两个文件；运行同一解释器 -m pytest。',steps:['建立 calc.py 和 test_calc.py，运行测试。','故意把 sum(items) 改成 0，确认测试失败并阅读差异。','恢复正确代码；在编辑器为 return 行设断点，调试一次调用并查看 items。'],checks:['正确实现时测试通过','错误实现时测试确实失败','能指出失败断言对应的行为'],quiz:{q:'一个测试在故意写错后仍然通过，说明什么？',options:['错误实现更优秀','测试可能没有覆盖目标行为','无需继续检查'],answer:1,explanation:'验证测试能发现错误，才能避免只有“绿色通过”的表面安全感。'},hint:'测试文件名以 test_ 开头，测试函数名也以 test_ 开头。',reflection:'先写失败用例，再修 bug，为什么有助于避免问题回归？',source:'https://docs.pytest.org/en/stable/getting-started.html'});
guide({id:'fa-01',track:'fastapi',title:'启动第一个 FastAPI 服务',intro:'你已经写过函数，现在让浏览器通过 HTTP 调用它。服务进程必须保持运行，浏览器才能连接。',concept:'FastAPI() 创建应用；@app.get("/") 把路径和函数绑定。装饰器前缀 @ 可以理解为给函数登记一条规则。',example:'from fastapi import FastAPI\n\napp = FastAPI()\n\n@app.get("/")\ndef home():\n    return {"message": "你好，接口"}',explain:'创建独立项目和虚拟环境，安装 "fastapi[standard]"。把示例存为 main.py；用虚拟环境的 Python 运行 -m uvicorn main:app --reload。main 是模块文件名，app 是文件中的应用变量。',steps:['在新项目虚拟环境安装 fastapi[standard]。','保存 main.py，运行 .\\.venv\\Scripts\\python.exe -m uvicorn main:app --reload。','打开 http://127.0.0.1:8000/ 和 /docs，确认 JSON 与交互文档。'],checks:['终端显示服务已启动','首页返回正确 JSON','/docs 可以调用接口'],quiz:{q:'main:app 中的 app 指什么？',options:['名为 app 的文件夹','main.py 中的应用对象','浏览器名称'],answer:1,explanation:'服务器从 main 模块导入 app 对象并处理请求。'},hint:'先确认文件叫 main.py，启动命令运行在同一目录。',reflection:'关闭服务进程后，浏览器还能访问接口吗？'});
guide({id:'fa-02',track:'fastapi',title:'路径参数与查询参数',intro:'获取某个任务和筛选一批任务，是两种不同的请求需求。',concept:'路径里的 {task_id} 指向特定资源；问号后是查询参数。类型注解 int 帮助框架转换和验证输入。',example:'@app.get("/tasks/{task_id}")\ndef get_task(task_id: int, detail: bool = False):\n    return {"id": task_id, "detail": detail}',explain:'这段代码加到上一课 main.py 的 app 定义之后。/tasks/3?detail=true 会得到 id=3 和 detail=true。字符串 abc 无法转换成整数，会被拒绝。',steps:['添加示例路由，在 /docs 调用 task_id=3。','设置 detail=true，再观察 JSON 的布尔值。','访问 /tasks/abc，查看验证错误。'],checks:['正常 id 返回整数','detail 能改变响应','错误 id 得到验证错误'],quiz:{q:'类型注解在这里有什么实际作用？',options:['只有好看，没有作用','帮助验证请求并生成文档','自动建立数据库'],answer:1,explanation:'FastAPI 使用注解参与请求解析和校验，但仍需要你定义业务规则。'},hint:'查询参数写在 ? 之后；路径参数必须与装饰器中的名字一致。',reflection:'有效整数 id=999 是否代表任务一定存在？'});
guide({id:'fa-03',track:'fastapi',title:'请求体与数据校验',intro:'创建任务需要传入结构化数据。数据模型规定客户端必须给哪些字段。',concept:'Pydantic BaseModel 定义请求体。Field 可声明长度和范围约束。语法合法不等于业务合法，因此要明确边界。',example:'from pydantic import BaseModel, Field\n\nclass TaskIn(BaseModel):\n    title: str = Field(min_length=1, max_length=100)\n\n@app.post("/tasks", status_code=201)\ndef create_task(task: TaskIn):\n    return {"id": 1, "title": task.title}',explain:'将示例追加到已有应用。当前返回固定 id，只用于学习请求体；综合项目会实现真正的持久化与唯一编号。',steps:['在 /docs 的 POST /tasks 里提交 {"title":"读源码"}。','提交空标题，观察验证响应。','提交 101 个字符，确认长度限制生效。'],checks:['合法请求返回 201','空字符串被拒绝','超长标题被拒绝'],quiz:{q:'min_length=1 能拒绝只含空格的标题吗？',options:['总是可以','不可以，还需要去空白等业务校验','会自动删除所有空格'],answer:1,explanation:'字符串长度为 1 的空格仍符合长度要求，业务层应 strip 后再验证。'},hint:'请求体必须是 JSON 对象，字段名称为 title。',reflection:'输入校验、业务校验、数据库约束分别放在哪里？'});
guide({id:'fa-04',track:'fastapi',title:'错误响应与分层',intro:'不存在的任务不应该伪装成一个成功结果。明确的错误契约方便调用者处理。',concept:'路由层处理 HTTP，服务层表达业务，仓储层读写数据。HTTPException 明确返回状态码和错误详情。',example:'from fastapi import HTTPException\n\ntasks = {1: {"id": 1, "title": "学习"}}\n\n@app.get("/items/{task_id}")\ndef read_item(task_id: int):\n    task = tasks.get(task_id)\n    if task is None:\n        raise HTTPException(status_code=404, detail="任务不存在")\n    return task',explain:'内存字典会在服务重启后消失。本节只练错误处理；数据持久化在项目中完成。',steps:['添加 /items/{task_id} 路由。','对比访问 id=1 与 id=999。','将 tasks.get 包装成独立函数 find_task，保持接口行为不变。'],checks:['已有任务返回 200','不存在返回 404','查找函数与 HTTP 处理分离'],quiz:{q:'仓储函数找不到数据时，哪种设计更方便复用？',options:['直接打开浏览器','返回 None，由上层决定如何表达错误','把所有错误改成 200'],answer:1,explanation:'数据访问层不必绑定具体展示方式，路由层可以把业务结果映射为 HTTP。'},hint:'先提取 def find_task(task_id): return tasks.get(task_id)。',reflection:'CLI 工具复用 find_task 时，为什么不希望它只能抛 HTTP 错误？'});
guide({id:'fa-05',track:'fastapi',title:'为接口写自动化测试',intro:'用浏览器手动点接口很直观，但代码变多后，要让测试帮你守住接口约定。',concept:'TestClient 可以在测试中调用应用。assert 不只检查状态码，还检查响应体的关键字段。',example:'from fastapi.testclient import TestClient\nfrom main import app\n\nclient = TestClient(app)\n\ndef test_home():\n    response = client.get("/")\n    assert response.status_code == 200\n    assert response.json()["message"] == "你好，接口"',explain:'保存为 test_main.py，安装 pytest 和 httpx，然后运行虚拟环境 Python -m pytest。测试不要依赖上一轮遗留数据。',steps:['运行首页测试。','为上一课不存在的任务补一个 404 测试。','故意把错误响应改成 200，确认新增测试会失败，再恢复。'],checks:['至少有成功与不存在两类测试','测试能在错误实现上失败','恢复后全部通过'],quiz:{q:'测试只 assert response.status_code == 200 的不足是什么？',options:['无法发现响应内容不符合约定','运行太快','HTTP 测试不能用 assert'],answer:0,explanation:'状态码只是契约的一部分，还要验证数据结构和业务值。'},hint:'测试函数内调用 client.get("/items/999")。',reflection:'如何避免测试向真实业务数据库写入数据？',source:'https://fastapi.tiangolo.com/tutorial/testing/'});
guide({id:'fa-06',track:'fastapi',title:'异步、配置与运行边界',intro:'服务可能需要等待数据库或模型响应。正确使用异步能帮助处理等待，但它不等于让所有计算变快。',concept:'async def 声明协程，await 等待可异步执行的操作。阻塞函数直接放在异步路由里可能阻塞事件循环。配置和密钥应从环境读取。',example:'import asyncio\nimport os\n\n@app.get("/health")\nasync def health():\n    await asyncio.sleep(0.01)\n    return {"status": "ok", "mode": os.getenv("APP_MODE", "dev")}',explain:'本例使用异步等待演示机制。实际 HTTP 请求要配置超时；不要把真实密钥写入代码或返回给客户端。--reload 适合开发，不是生产部署方案。',steps:['添加 health 路由，调用并查看结果。','在 PowerShell 设置 $env:APP_MODE="test"，重启服务确认配置变化。','写下模型请求超时、日志脱敏、访问鉴权三项后续工作。'],checks:['能解释 await 的作用','配置通过环境传入','知道开发模式与正式部署的区别'],quiz:{q:'在 async 路由里直接 time.sleep(10) 会怎样？',options:['自动并行计算','阻塞当前事件循环，影响其他请求','自动变成 await'],answer:1,explanation:'同步阻塞等待不会自动变成异步，必须选择合适的接口或执行方式。'},hint:'环境变量设置后，新启动的进程才会读取它。',reflection:'并发、并行和异步分别解决什么问题？',source:'https://fastapi.tiangolo.com/async/'});
guide({id:'java-01',track:'java',title:'安装 JDK，运行第一段 Java',intro:'Java 通常先编译成字节码，再由 JVM 执行。JDK 提供编译和运行工具。',concept:'类名与 public class 所在文件名保持一致。main 是本课程序的入口。分号结束语句，花括号划定代码块。',example:'public class Main {\n    public static void main(String[] args) {\n        System.out.println("你好，Java！");\n    }\n}',explain:'从 dev.java 获取 JDK 安装指引。使用 JDK 21 或与所选 Spring 版本兼容的 JDK。保存 Main.java，在目录里运行 javac Main.java，再 java Main。',steps:['在终端确认 java -version 和 javac -version 可用。','保存并编译 Main.java，找到生成的 Main.class。','运行 java Main，修改问候语后重新编译再运行。'],checks:['java 与 javac 都能使用','编译生成 class 文件','能解释源文件与字节码区别'],quiz:{q:'改了 Main.java 但直接运行旧 Main.class，会看到什么？',options:['新代码必然自动生效','仍可能是上次编译的行为','JVM 会删除源码'],answer:1,explanation:'源码修改后需要重新编译，这与网页中直接运行 Python 的流程不同。'},hint:'文件名 Main.java 的大小写与 public class Main 保持一致。',reflection:'JDK、JVM 和 Java 源码分别是什么？'});
guide({id:'java-02',track:'java',title:'类型、判断和循环',intro:'Java 要求变量具有明确类型，这能让编译器在运行前发现一部分错误。',concept:'int 保存整数，double 保存小数，boolean 保存真假，String 保存文字。for 的增强写法可以遍历数组。',example:'public class Main {\n    public static void main(String[] args) {\n        int[] scores = {55, 60, 90};\n        for (int score : scores) {\n            if (score >= 60) {\n                System.out.println(score);\n            }\n        }\n    }\n}',explain:'与 Python 的缩进不同，Java 用花括号决定语句归属。保持良好缩进仍然非常重要。',steps:['编译运行示例，观察输出 60 和 90。','增加变量 count，统计及格人数。','把数组改为空数组，确认 count 为 0。'],solution:'public class Main {\n    public static void main(String[] args) {\n        int[] scores = {55, 60, 90};\n        int count = 0;\n        for (int score : scores) {\n            if (score >= 60) count++;\n        }\n        System.out.println(count);\n    }\n}',checks:['原数据输出人数 2','空数组输出人数 0','能够解释 int 与 String'],quiz:{q:'int count = "2"; 有什么问题？',options:['文字不能直接赋给 int','没有问题','会自动变成数组'],answer:0,explanation:'Java 的静态类型检查会拒绝这种赋值，应显式解析数字文本。'},hint:'在循环外 int count = 0，在及格分支 count++。',reflection:'编译成功是否代表业务逻辑正确？'});
guide({id:'java-03',track:'java',title:'类、对象与封装',intro:'任务有标题和完成状态。通过类定义它们，通过方法控制状态变化。',concept:'private 隐藏内部字段；public 方法提供明确操作；构造函数初始化对象。封装帮助维持业务约束。',example:'public class Main {\n    static class Task {\n        private final String title;\n        private boolean done;\n        Task(String title) { this.title = title; }\n        void complete() { this.done = true; }\n        boolean isDone() { return done; }\n    }\n    public static void main(String[] args) {\n        Task task = new Task("学习");\n        task.complete();\n        System.out.println(task.isDone());\n    }\n}',explain:'this 表示当前对象。final 字段在构造后不能重新赋值。任务的 done 初始为 false。',steps:['运行示例，确认输出 true。','去掉 complete 调用，观察 false。','创建第二个 Task，确认第一个任务完成不会影响第二个。'],checks:['能追踪状态从 false 到 true','两个对象的状态相互独立','能解释 private 与 final'],quiz:{q:'为什么通过 complete 方法修改状态？',options:['只能为了减少字符','能集中控制状态变化规则','让所有对象共享状态'],answer:1,explanation:'以后需要记录完成时间或检查权限时，可以在明确的行为入口处理。'},hint:'在 main 中新增 Task second = new Task("复盘")。',reflection:'对象状态在哪一行被修改？这个方法是否有副作用？'});
guide({id:'java-04',track:'java',title:'接口：依赖一种能力',intro:'通知可以通过终端、邮件或其他方式发送。业务代码不必绑定具体实现。',concept:'interface 描述方法契约，implements 提供实现。调用者依赖接口，就能替换实现而不修改业务流程。',example:'public class Main {\n    interface Notifier { void send(String text); }\n    static class ConsoleNotifier implements Notifier {\n        public void send(String text) { System.out.println(text); }\n    }\n    static void finish(Notifier notifier) { notifier.send("完成"); }\n    public static void main(String[] args) { finish(new ConsoleNotifier()); }\n}',explain:'finish 只知道 notifier 能 send，不需要知道输出发生在哪里。测试时可以传入记录消息的假实现。',steps:['运行示例。','新增 QuietNotifier，实现 send 但不输出。','把 main 中实现替换掉，确认 finish 不需要改。'],checks:['能添加第二种接口实现','调用方不依赖具体实现','能说明接口契约'],quiz:{q:'依赖接口的主要价值是什么？',options:['让任何错误消失','减少调用方与具体实现的耦合','自动提升运行速度'],answer:1,explanation:'接口隔离了调用方式和实现细节，但仍需要测试契约是否被遵守。'},hint:'实现类的方法需要 public，否则可见性不满足接口要求。',reflection:'Python 中如何用可调用对象或协议实现类似替换？'});
guide({id:'java-05',track:'java',title:'集合与泛型',intro:'实际应用会保存一组任务和按编号查找的数据。Java 集合提供常用的数据结构。',concept:'List 保留顺序，Map 按键查找，Set 保存不重复元素。List&lt;String&gt; 约束列表元素是字符串。',example:'import java.util.*;\npublic class Main {\n    public static void main(String[] args) {\n        List<String> tasks = new ArrayList<>();\n        tasks.add("学习");\n        tasks.add("复盘");\n        Map<String, Integer> counts = new HashMap<>();\n        for (String task : tasks) {\n            counts.put(task, counts.getOrDefault(task, 0) + 1);\n        }\n        System.out.println(counts.get("学习"));\n    }\n}',explain:'泛型使用包装类型 Integer，而不是基本类型 int。HashMap 的遍历顺序不应当作稳定的输出顺序。',steps:['运行示例，输出应为 1。','再添加一次 "学习"，确认计数为 2。','通过 getOrDefault 为不存在的键返回 0。'],checks:['能够统计重复元素','能处理不存在的键','知道 Map 不保证这里的展示顺序'],quiz:{q:'为什么不能假设 HashMap 总按插入顺序输出？',options:['它的契约不保证这种顺序','Java 不支持顺序','因为有中文'],answer:0,explanation:'需要特定顺序时应显式选择合适的数据结构或排序。'},hint:'对不存在的键直接 get 可能得到 null。',reflection:'List、Set、Map 分别对应 Python 的哪些常见结构？'});
guide({id:'java-06',track:'java',title:'异常处理与资源关闭',intro:'文件打不开、数字解析失败、网络超时都属于需要考虑的失败路径。',concept:'try/catch 处理特定异常；try-with-resources 自动关闭实现 AutoCloseable 的资源。错误信息应帮助定位原因。',example:'public class Main {\n    static Integer parse(String text) {\n        try { return Integer.parseInt(text); }\n        catch (NumberFormatException e) { return null; }\n    }\n    public static void main(String[] args) {\n        System.out.println(parse("12"));\n        System.out.println(parse("abc"));\n    }\n}',explain:'Integer 允许 null，而 int 不允许。返回 null 的契约要求调用者在使用前检查；更复杂项目可使用更明确的结果类型。',steps:['编译运行，确认输出 12 和 null。','增加 "-3" 与空字符串的测试调用。','在笔记里写清 parse 的输入、返回值与失败规则。'],checks:['有效数字正确解析','无效文本进入失败分支','能解释 int 与 Integer 在本例中的区别'],quiz:{q:'捕获 Exception 后直接返回 0 的风险是什么？',options:['会把真实错误伪装成合法数据','可以修好所有 bug','Java 不允许 0'],answer:0,explanation:'错误被吞掉后，调用者可能把失败值继续用于业务计算。'},hint:'只处理预期的 NumberFormatException，并明确告知调用者失败。',reflection:'异常是在哪一行产生，又在哪一层被处理？'});
guide({id:'java-07',track:'java',title:'Maven、模块与自动测试',intro:'项目变大以后，不可能手工管理每个依赖文件。Maven 统一管理构建、依赖和测试。',concept:'pom.xml 描述项目。src/main/java 放业务代码，src/test/java 放测试。依赖坐标由 groupId、artifactId、version 组成。',example:'src/\n  main/java/com/example/Calculator.java\n  test/java/com/example/CalculatorTest.java\npom.xml\nmvnw.cmd',explain:'下一阶段使用 Spring Initializr 生成带 Maven Wrapper 的项目，避免自己拼装构建配置。先打开生成的 pom.xml，找出依赖区和 Java 版本。Windows 用 .\\mvnw.cmd test 运行测试。',steps:['从 start.spring.io 生成 Maven Java 项目，选择稳定版本和兼容 JDK。','打开 pom.xml，指出项目坐标、Java 版本和依赖。','运行 .\\mvnw.cmd test，观察测试报告位置 target/surefire-reports。'],checks:['能找到依赖声明位置','Wrapper 可以执行测试','能区分 src 和 target 目录'],quiz:{q:'阅读源码时应该优先读 target 吗？',options:['是，它一定是手写业务代码','通常不是，它主要包含生成的构建产物','所有代码只在 target'],answer:1,explanation:'先看 src 里的源文件与构建配置，避免把生成代码当成主要设计来源。'},hint:'首次 Wrapper 会下载所需组件，需要联网。',reflection:'依赖树中的传递依赖是什么意思？',source:'https://maven.apache.org/guides/getting-started/'});
guide({id:'sb-01',track:'springboot',title:'Spring Boot：从入口启动应用',intro:'Spring Boot 帮你组织 Java 应用并配置常见基础设施。先看清生成的项目，再添加接口。',concept:'@SpringBootApplication 标识启动配置，SpringApplication.run 启动应用上下文。它会发现并组装约定范围内的组件。',example:'package com.example.demo;\nimport org.springframework.boot.SpringApplication;\nimport org.springframework.boot.autoconfigure.SpringBootApplication;\n\n@SpringBootApplication\npublic class DemoApplication {\n    public static void main(String[] args) {\n        SpringApplication.run(DemoApplication.class, args);\n    }\n}',explain:'在 start.spring.io 选择 Maven、Java、Spring Web，生成项目。保留生成器给出的兼容版本组合。确认 JDK 满足该版本要求，不要把不同教程的依赖版本混拼。',steps:['生成并解压项目，找到 Application 启动类。','运行 .\\mvnw.cmd spring-boot:run。','确认启动日志中的端口；此时首页 404 正常，因为还未定义路由。'],checks:['应用正常启动','能定位 main 入口','知道此时 404 不代表启动失败'],quiz:{q:'服务已启动但首页 404，首先检查什么？',options:['有没有注册对应路由','立即重装 JDK','删除整个项目'],answer:0,explanation:'程序启动和某个路径是否存在，是两件不同的事。'},hint:'源文件包名需要与生成器项目一致，示例使用 com.example.demo。',reflection:'组件扫描的包范围会怎样影响类是否被发现？',source:'https://spring.io/guides/gs/spring-boot'});
guide({id:'sb-02',track:'springboot',title:'Controller：接收 HTTP 请求',intro:'Controller 是请求进入业务代码的一扇门，负责把 HTTP 参数转换为方法输入。',concept:'@RestController 表示返回响应数据；@GetMapping 将路径映射到方法；@PathVariable 读取路径参数。',example:'package com.example.demo;\nimport java.util.Map;\nimport org.springframework.web.bind.annotation.*;\n\n@RestController\npublic class HelloController {\n    @GetMapping("/hello/{name}")\n    public Map<String, String> hello(@PathVariable("name") String name) {\n        return Map.of("message", "你好，" + name);\n    }\n}',explain:'新建 HelloController.java，放在启动类相同包下。浏览器访问 /hello/Xiaobai，返回 JSON。',steps:['创建 Controller 并重启应用。','访问 http://127.0.0.1:8080/hello/Xiaobai。','修改响应字段后，观察客户端收到的 JSON 变化。'],checks:['路由可访问','路径参数进入方法','能够对应 Java Map 与 JSON'],quiz:{q:'@RestController 的方法返回 Map 时，本例客户端收到什么？',options:['Java 源文件','序列化后的 JSON 数据','JVM 字节码'],answer:1,explanation:'框架将返回值交给消息转换组件生成 HTTP 响应。'},hint:'类必须放在被应用扫描到的包下。',reflection:'一次请求从路径匹配到 JSON 输出，经过了哪些层？',source:'https://spring.io/guides/gs/rest-service'});
guide({id:'sb-03',track:'springboot',title:'依赖注入与 Service 分层',intro:'Controller 里塞满计算和数据库访问，会让代码越来越难测试。把业务行为放到 Service。',concept:'依赖注入表示对象所依赖的组件由外部提供。构造函数清晰列出依赖，便于测试时替换。',example:'// GreetingService.java\npackage com.example.demo;\nimport org.springframework.stereotype.Service;\n@Service\npublic class GreetingService {\n    public String greet(String name) { return "你好，" + name; }\n}',explain:'在 HelloController 中新增 private final GreetingService service；提供构造函数赋值，然后用 service.greet(name) 替代字符串拼接。Spring 会提供这个 Service。',steps:['建立 GreetingService.java。','通过构造函数把它传入 Controller。','调用原接口，确认对外行为保持一致。'],solution:'package com.example.demo;\nimport java.util.Map;\nimport org.springframework.web.bind.annotation.*;\n@RestController\npublic class HelloController {\n    private final GreetingService service;\n    public HelloController(GreetingService service) { this.service = service; }\n    @GetMapping("/hello/{name}")\n    public Map<String,String> hello(@PathVariable("name") String name) {\n        return Map.of("message", service.greet(name));\n    }\n}',checks:['业务逻辑移到 Service','通过构造函数声明依赖','原接口行为不变'],quiz:{q:'构造函数注入的好处是什么？',options:['依赖清晰，测试可传入替代实现','自动生成所有业务代码','让数据库无需连接'],answer:0,explanation:'显式依赖使对象更容易理解和组装，测试也不必靠隐藏的全局状态。'},hint:'Service 需要被 Spring 发现；不要遗漏 @Service。',reflection:'自己 new GreetingService 与由容器提供有什么差异？',source:'https://docs.spring.io/spring-framework/reference/core/beans/dependencies/factory-collaborators.html'});
guide({id:'sb-04',track:'springboot',title:'请求校验和一致的错误契约',intro:'服务不能完全信任输入。标题为空、长度过长等情况应该在边界处清楚拒绝。',concept:'使用 Validation 依赖，@Valid 启用模型校验，@NotBlank 拒绝 null、空字符串及只含空白的内容。',example:'package com.example.demo;\nimport jakarta.validation.constraints.NotBlank;\nimport jakarta.validation.constraints.Size;\npublic record TaskRequest(\n    @NotBlank @Size(max = 100) String title\n) {}',explain:'通过 Initializr 为项目添加 Validation 依赖，或按同一版本的构建配置添加对应 starter。Controller 的 POST 方法使用 @Valid @RequestBody TaskRequest request。',steps:['创建 TaskRequest.java，添加合法性约束。','新增 POST /tasks 并启用 @Valid。','提交正常标题、空字符串和全空格，对比状态码。'],solution:'// Controller 中的方法；需导入 jakarta.validation.Valid\n@PostMapping("/tasks")\npublic Map<String,String> create(@Valid @RequestBody TaskRequest request) {\n    return Map.of("title", request.title());\n}',checks:['合法标题成功','空白标题被拒绝','字段约束与业务规则能区分'],quiz:{q:'@NotBlank 比单纯判断长度更适合标题的原因？',options:['可以拒绝只含空格的文本','自动保存数据库','自动做身份认证'],answer:0,explanation:'字段非空和用户身份是不同问题，验证标题不代表完成了访问控制。'},hint:'没有 Validation 依赖或 @Valid，约束可能不会按预期生效。',reflection:'业务冲突、格式错误、权限错误应返回同一种状态吗？',source:'https://spring.io/guides/gs/validating-form-input'});
guide({id:'sb-05',track:'springboot',title:'Repository 与事务边界',intro:'数据访问应该有清晰入口。先理解仓储接口，再用数据库实现保存和查找。',concept:'Repository 屏蔽持久化细节。事务通常包围一个完整业务操作，而不是随意包住单条语句。Entity 表示数据库映射对象，DTO 表示接口传输对象。',example:'Controller → Service → Repository → Database\n\n创建任务：\n1. 校验输入\n2. Service 应用业务规则\n3. Repository 保存\n4. 返回响应 DTO',explain:'这是结构示意，不是可编译 Java。综合项目给出 JdbcTemplate 与 H2 的完整实现。先避免一边学习一边同时引入多个持久化框架。',steps:['打开实战项目“Java 任务服务”，查看 Repository 的实现。','找出 SQL 的执行位置与参数绑定。','说明如果保存后还要写审计记录，事务应覆盖哪两步。'],checks:['能定位真实 SQL 执行位置','能解释参数绑定','能描述业务操作的事务边界'],quiz:{q:'用户输入应该怎样传入 SQL？',options:['字符串直接拼接','使用参数绑定','把引号删除就安全'],answer:1,explanation:'参数绑定区分数据与 SQL 结构，不能靠简单字符串替换代替。'},hint:'查找 jdbc.update 和 jdbc.query；问号是参数占位符。',reflection:'数据库故障时，业务层需要回滚哪些副作用？',source:'https://spring.io/guides/gs/relational-data-access'});
guide({id:'sb-06',track:'springboot',title:'验证配置、接口与持久化',intro:'能启动只完成了第一步。你还需要证明接口行为和数据保存符合要求。',concept:'分层测试可以分别验证服务逻辑和 HTTP 行为。测试数据库应与真实数据隔离。配置差异通过 profile 或环境显式管理。',example:'./mvnw.cmd test\n./mvnw.cmd spring-boot:run\n\n# 应用启动后，在另一个 PowerShell 终端调用\nInvoke-RestMethod http://127.0.0.1:8080/tasks',explain:'使用项目中的验收清单测试创建、列表和非法输入。仅用内存 H2 时重启数据会丢失；文件 H2 则可以持久保存。要能解释配置产生的差异。',steps:['完成 Java 任务服务的成功与非法输入测试。','重启服务，检查数据是否保留，并对照数据源配置。','把端口改为 8081，再测试客户端 URL 是否同步调整。'],checks:['完成接口成功与失败检查','验证过服务重启后的数据行为','能定位服务端口和数据源配置'],quiz:{q:'测试应依赖上一次手动运行留下的数据吗？',options:['应该，这样更真实','不应，应建立可控、可重复的数据条件','所有测试都不需要数据'],answer:1,explanation:'不可控状态会让测试偶尔通过、偶尔失败，难以用作修改证据。'},hint:'每个测试应准备所需数据，并清理或隔离它创建的状态。',reflection:'怎样区分“代码问题”和“环境配置问题”？',source:'https://docs.spring.io/spring-boot/reference/testing/index.html'});

